async def wait_state(p,fn,timeout=15):
 end=time.monotonic()+timeout
 while time.monotonic()<end:
  s=await snap(p)
  if fn(s):return s
  await p.wait_for_timeout(15)
 raise AssertionError('Timed out '+json.dumps(await snap(p)))
